import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1787828411000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Node.js ≥ 22</li><li>A Woodpecker server you can reach, and an account on it</li></ul><h2 id="get-a-token" tabindex="-1">Get a token <a class="header-anchor" href="#get-a-token" aria-label="Permalink to “Get a token”">​</a></h2><p>In Woodpecker: your avatar → <strong>User settings</strong> → <strong>CLI and API</strong>. The page shows your personal access token.</p><p>There are no scopes and no read-only variant: <strong>the token is your account</strong>. If that account is an instance administrator, the token can do everything an administrator can — every repository, every secret, every agent. Two things follow from that:</p><ul><li>Use <code>WOODPECKER_READ_ONLY=true</code> unless you actually want this server to change things.</li><li>Prefer a normal account over an admin one. The admin-only tools will answer 403 and everything else works.</li></ul><h2 id="configure-it" tabindex="-1">Configure it <a class="header-anchor" href="#configure-it" aria-label="Permalink to “Configure it”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">export</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> WOODPECKER_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">https://woodpecker.example.com</span></span>
<span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">export</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> WOODPECKER_TOKEN</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">...</span></span></code></pre></div><p><code>WOODPECKER_URL</code> is the <strong>server root</strong>, the URL you open in a browser — not <code>.../api</code>. Both spellings are accepted (the suffix is trimmed), because the Swagger page spells every example the long way.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to “Run it”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/woodpecker-ci-mcp</span></span></code></pre></div><p>It speaks MCP over stdio, so on its own it will just sit there. See <a href="/guide/clients">connecting clients</a> for wiring it into Claude Code, Claude Desktop or Codex, or try it directly:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npx</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @modelcontextprotocol/inspector</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/woodpecker-ci-mcp</span></span></code></pre></div><h2 id="check-that-it-works" tabindex="-1">Check that it works <a class="header-anchor" href="#check-that-it-works" aria-label="Permalink to “Check that it works”">​</a></h2><p>Call <code>get_server_info</code> first. It needs no token, so it separates the two things that can be wrong:</p><ul><li><strong>It answers with a version</strong> → <code>WOODPECKER_URL</code> is right. If other tools then fail with 401, the token is the problem.</li><li><strong>It fails saying Woodpecker answered with HTML</strong> → the URL reaches a web page rather than the API. That is what a wrong host, a proxy or an SSO portal in front of the instance looks like, because Woodpecker serves its UI from the same origin and answers unrouted paths with the single-page app — with HTTP 200, not a 404.</li></ul><p>Then <code>get_current_user</code>, which tells you which account the token belongs to and whether it is an administrator.</p><h2 id="find-a-repository" tabindex="-1">Find a repository <a class="header-anchor" href="#find-a-repository" aria-label="Permalink to “Find a repository”">​</a></h2><p>Everything else takes a numeric <code>repo_id</code>, and nothing in the web UI shows it. Two ways to get one:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>lookup_repository(full_name: &quot;acme/widgets&quot;)</span></span>
<span class="line"><span>list_repositories()</span></span></code></pre></div><p>A repository that plainly exists in your forge but answers 404 here has simply never been activated in Woodpecker. <code>list_repositories(include_inactive: true)</code> lists those too, and <code>activate_repository</code> turns one on.</p>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};